import type { CategorySlug, CollectionSlug, PublicationStatus, ReviewArea } from "./framework/types";

/**
 * Master backlog of calculator concepts, deduplicated by id and name.
 *
 * - "published" entries must match a published registry record with the same id.
 * - Scores are 1–5 editorial estimates: usefulness and demand (higher is better)
 *   and difficulty (higher is harder). Demand is not yet backed by search data.
 * - `review` flags topics that need a qualified professional before publishing
 *   or before relying on the result.
 *
 * Regenerate docs/calculator-backlog.md with `npm run backlog:report`.
 */
export interface BacklogItem {
  id: string;
  name: string;
  category: CategorySlug;
  collections: CollectionSlug[];
  status: PublicationStatus;
  usefulness: 1 | 2 | 3 | 4 | 5;
  demand: 1 | 2 | 3 | 4 | 5;
  difficulty: 1 | 2 | 3 | 4 | 5;
  review?: ReviewArea;
  notes?: string;
  /** Likely formula or method, for planning; verify against a source before building. */
  formula?: string;
  /** Data, parsers or shared components the calculator needs first. */
  dependencies?: string;
  /** What must be checked before publishing (sources, reference values, expert review). */
  verification?: string;
  /**
   * Public page where the topic was found, used for topic discovery only (never
   * for wording, layout or code). Omni Calculator URLs were taken from web
   * search result listings; the pages themselves could not be opened.
   */
  reference?: string;
}

/** Higher is more urgent: usefulness and demand count double, difficulty counts against. */
export function priorityScore(item: Pick<BacklogItem, "usefulness" | "demand" | "difficulty">): number {
  return 2 * item.usefulness + 2 * item.demand - item.difficulty;
}

